    /// <summary>
    /// Gets the configuration settings for the specified browser profile.
    /// </summary>
    public static ProfileConfig GetSettings(BrowserProfile profile)
    {
        if (Settings.TryGetValue(profile, out var config))
        {
            return config;
        }

        throw new ArgumentException($"Unknown browser profile: {profile}", nameof(profile));
    }
